// Enhanced Parse Slack with Name→ID Resolution
const slackMessage = $input.first().json;
const text = (slackMessage.text || '').toLowerCase().trim();
const cleanText = text.replace(/<@[A-Z0-9]+>/g, '').trim();

const output = {
  raw_text: cleanText,
  action: null,
  ticket_id: null,
  customer_email: null,
  assignee: null,
  assignee_id: null,
  tags: null,
  status: null,
  priority: null,
  message: null,
  note: null,
  subject: null,
  intent: null,
  time_range: null,
  filters: {},
  channel: slackMessage.channel,
  thread_ts: slackMessage.thread_ts || slackMessage.ts,
  user: slackMessage.user
};

// Extract ticket ID
const ticketMatch = cleanText.match(/ticket\s+#?(\d+)|#(\d+)/);
if (ticketMatch) output.ticket_id = ticketMatch[1] || ticketMatch[2];

// Extract email
const emailMatch = cleanText.match(/([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+)/);
if (emailMatch) output.customer_email = emailMatch[1];

// Extract assignee name
const assigneeMatch = cleanText.match(/(?:assign(?:ed)?\s+to|for)\s+([a-z]+)/i);
if (assigneeMatch) output.assignee = assigneeMatch[1];

// Extract status
const statusKeywords = ['open', 'closed', 'snoozed', 'spam', 'deleted'];
for (const status of statusKeywords) {
  if (cleanText.includes(status)) {
    output.status = status;
    break;
  }
}

// Extract priority
if (cleanText.match(/\b(low|normal|high|critical|urgent)\b/i)) {
  const priorityMatch = cleanText.match(/\b(low|normal|high|critical|urgent)\b/i);
  output.priority = priorityMatch[1].charAt(0).toUpperCase() + priorityMatch[1].slice(1);
  if (output.priority === 'Urgent') output.priority = 'Critical';
}

// Extract tags
const tagMatch = cleanText.match(/tag(?:s)?\s+(?:with\s+)?([\w\s,]+)/);
if (tagMatch) {
  output.tags = tagMatch[1].split(',').map(t => t.trim());
}

// Extract message/note
const messageMatch = cleanText.match(/(?:reply|message|say)\s+["'](.+?)["']/);
if (messageMatch) output.message = messageMatch[1];

const noteMatch = cleanText.match(/(?:note|comment)\s+["'](.+?)["']/);
if (noteMatch) output.note = noteMatch[1];

// Detect analytical intent
if (cleanText.match(/how many|count|total|number of/)) {
  if (cleanText.includes('assign')) {
    output.intent = 'assignee_workload';
  } else {
    output.intent = 'ticket_volume';
  }
} else if (cleanText.match(/recurring|repeated|common|frequent/)) {
  output.intent = 'recurring_questions';
} else if (cleanText.match(/sla|resolution time|response time|performance/)) {
  output.intent = 'sla_performance';
} else if (cleanText.match(/tag.*trend|popular tags/)) {
  output.intent = 'tag_trends';
} else if (cleanText.match(/insights|digest|overview|summary/)) {
  output.intent = 'comprehensive_insights';
} else if (cleanText.match(/agent.*performance|team.*stats/)) {
  output.intent = 'agent_performance';
} else if (cleanText.match(/priority.*distribution/)) {
  output.intent = 'priority_distribution';
}

// Action detection (preliminary)
if (cleanText.includes('get') || cleanText.includes('show') || cleanText.includes('view') || cleanText.includes('list')) {
  output.action = 'read';
} else if (cleanText.includes('create') || cleanText.includes('new ticket')) {
  output.action = 'create';
} else if (cleanText.includes('close') || cleanText.includes('update') || cleanText.includes('change') || cleanText.includes('set')) {
  output.action = 'update';
} else if (cleanText.includes('assign')) {
  output.action = 'assign';
} else if (cleanText.includes('search') || cleanText.includes('find')) {
  output.action = 'search';
} else if (cleanText.includes('tag')) {
  output.action = 'tag';
} else if (cleanText.includes('reply') || cleanText.includes('message') || cleanText.includes('note')) {
  output.action = 'message';
}

// NAME→ID RESOLUTION: Call Gorgias API if assignee name detected
if (output.assignee && !output.assignee_id) {
  try {
    const response = await this.helpers.httpRequestWithAuthentication.call(this, 'httpBasicAuth', {
      method: 'GET',
      url: `https://ironsidecomputers.gorgias.com/api/users`,
      json: true
    });

    if (response.data && response.data.length > 0) {
      // Find user by matching name (case-insensitive)
      const user = response.data.find(u => 
        u.firstname?.toLowerCase() === output.assignee.toLowerCase() ||
        u.lastname?.toLowerCase() === output.assignee.toLowerCase() ||
        u.email?.toLowerCase().includes(output.assignee.toLowerCase())
      );
      if (user) {
        output.assignee_id = user.id;
      }
    }
  } catch (error) {
    console.log('User lookup failed:', error.message);
  }
}

// Build filters
if (output.assignee_id) output.filters.assignee_user_id = output.assignee_id;
if (output.status) output.filters.status = output.status;
if (output.priority) output.filters.priority = output.priority;

return [output];

