// Build Slack reply from AI Agent output
const items = $input.all();
const aiOutput = items[0].json.output || items[0].json.text || items[0].json;
const parseSlackData = $('Parse Slack').first().json;

// If AI output is a string, use it directly
if (typeof aiOutput === 'string') {
  return [{
    json: {
      message_text: aiOutput,
      channel: parseSlackData.channel,
      thread_ts: parseSlackData.thread_ts
    }
  }];
}

// Otherwise format structured response
let message = '';

if (aiOutput.summary) {
  message = aiOutput.summary;
} else if (aiOutput.text) {
  message = aiOutput.text;
} else {
  message = '✅ Request completed successfully';
}

// Add details if available
if (aiOutput.details) {
  const details = aiOutput.details;
  if (details.ticket_id) message += `\n📋 Ticket: #${details.ticket_id}`;
  if (details.tickets_count) message += `\n📊 Count: ${details.tickets_count}`;
  if (details.status) message += `\n📊 Status: ${details.status}`;
  if (details.assignee) message += `\n👤 Assigned to: ${details.assignee}`;
  if (details.tags && details.tags.length > 0) message += `\n🏷️ Tags: ${details.tags.join(', ')}`;
}

// Add error context if needed
if (aiOutput.error) {
  message = `⚠️ Error: ${aiOutput.error}\n\n${message}`;
}

return [{
  json: {
    message_text: message,
    channel: parseSlackData.channel,
    thread_ts: parseSlackData.thread_ts
  }
}];
